import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Button, Header, Icon, Label, Loader, Message, Table } from 'semantic-ui-react';
import { showError, showSuccess } from '../../helpers';
import {
  cleanupDryRun,
  getFreePoolUsage,
  getGatewayConfig,
  getRuntimeStatus,
  reloadConfig,
  saveGatewayConfig,
  syncFreePool,
} from './gatewayConfigApi';
import FreeProvidersEditor from './FreeProvidersEditor';
import {
  buildFreePoolWorkflowSummary,
  indexUsageRows,
  isAutoFreeDeployment,
  loadFreePoolDashboardData,
  providerFromDeploymentId,
} from './freePoolUtils';
import FreePoolWorkflowDashboard from './FreePoolWorkflowDashboard';

const POOL_LABELS = {
  free: '免费池',
};

const STRATEGY_LABELS = {
  free_first: '免费优先',
};

const PROVIDER_LABELS = {
  openrouter: 'OpenRouter',
  groq: 'Groq',
  google: 'Google AI',
  kilo: 'Kilo',
  pollinations: 'Pollinations',
  ovh: 'OVH Cloud',
  nvidia: 'NVIDIA',
  cohere: 'Cohere',
  huggingface: 'Hugging Face',
  llm7: 'LLM7',
  opencode: 'OpenCode',
  aihorde: 'AI Horde',
  routeway: 'Routeway',
  bazaarlink: 'Bazaarlink',
  ainative: 'AINative',
  agnes: 'Agnes',
  reka: 'Reka',
};

const formatNumber = (value) => {
  const n = Number(value);
  if (!Number.isFinite(n)) return '-';
  return new Intl.NumberFormat('zh-CN').format(n);
};

const formatLimit = (value) => {
  if (value === undefined || value === null || value === '') return '默认';
  const n = Number(value);
  if (!Number.isFinite(n)) return '-';
  return n === 0 ? '不限' : formatNumber(n);
};

const formatQuotaMode = (value) => {
  if (!value || value === 'free') return '免费';
  return value;
};

const formatRuntimeHealth = (value) => {
  const health = String(value || '').toLowerCase();
  const labels = {
    valid: '正常',
    healthy: '正常',
    ok: '正常',
    invalid: '异常',
    critical: '严重',
    failed: '失败',
    warning: '警告',
    rate_limited: '限流',
    error: '异常',
    unknown: '未知',
  };
  return labels[health] || value || '已启用';
};

const getRuntimeHealthColor = (value) => {
  const health = String(value || '').toLowerCase();
  if (['invalid', 'critical', 'failed', 'error'].includes(health)) return 'red';
  if (['rate_limited', 'warning'].includes(health)) return 'yellow';
  if (health === 'unknown') return 'grey';
  return 'green';
};

const getRuntimeIssues = (runtime = {}) => {
  const issues = [
    runtime.cooldown_reason,
    runtime.state_last_error_message,
    runtime.last_error,
  ]
    .map((value) => String(value || '').trim())
    .filter(Boolean);
  return Array.from(new Set(issues));
};

const renderRuntimeDiagnostics = (runtime = {}) => {
  const stickyVirtualModels = Array.isArray(runtime.sticky_virtual_models)
    ? runtime.sticky_virtual_models
    : [];
  const issues = getRuntimeIssues(runtime);
  const hasDiagnostics = runtime.is_sticky
    || runtime.cooldown_active
    || runtime.exhausted_active
    || issues.length > 0;

  if (!hasDiagnostics) return null;

  return (
    <div className='free-deployment-runtime-diagnostics'>
      <div className='free-deployment-runtime-labels'>
        {runtime.is_sticky && (
          <Label basic color='blue' size='mini'>
            Sticky{stickyVirtualModels.length > 0 ? ` ${stickyVirtualModels.join(', ')}` : ''}
          </Label>
        )}
        {runtime.cooldown_active && (
          <Label basic color='yellow' size='mini'>Cooldown</Label>
        )}
        {runtime.exhausted_active && (
          <Label basic color='red' size='mini'>Exhausted</Label>
        )}
      </div>
      {issues.length > 0 && (
        <div className='free-deployment-runtime-issues'>
          {issues.map((issue) => (
            <div className='free-deployment-runtime-issue' key={issue}>
              {issue}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

const FreeModelPool = () => {
  const [config, setConfig] = useState(null);
  const [runtimeRows, setRuntimeRows] = useState([]);
  const [usageRows, setUsageRows] = useState([]);
  const [usageAvailable, setUsageAvailable] = useState(true);
  const [usageError, setUsageError] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [actingAction, setActingAction] = useState('');

  const loadAll = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      const {
        configData,
        runtimeData,
        usageRows: nextUsageRows,
        usageAvailable: nextUsageAvailable,
        usageError: nextUsageError,
      } = await loadFreePoolDashboardData({
        getGatewayConfig,
        getRuntimeStatus,
        getFreePoolUsage,
      });
      if (configData.success !== false && configData.data) {
        setConfig(configData.data);
      } else {
        showError(configData.message || '加载免费模型池失败');
      }
      if (runtimeData.success !== false) {
        setRuntimeRows(Array.isArray(runtimeData.data) ? runtimeData.data : []);
      }
      setUsageRows(nextUsageRows);
      setUsageAvailable(nextUsageAvailable !== false);
      setUsageError(nextUsageError || '');
    } catch (e) {
      showError(e.message || '加载免费模型池失败');
    } finally {
      if (!silent) setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadAll().then();
  }, [loadAll]);

  const updateFreeProviders = (updatedFreeProviders) => {
    setConfig((prev) => ({ ...prev, free_providers: updatedFreeProviders }));
  };

  const saveFreePoolConfig = async () => {
    if (!config) return;
    setSaving(true);
    try {
      const res = await saveGatewayConfig(config);
      const { success, data, message } = res.data || {};
      if (success !== false) {
        setConfig(data || config);
        showSuccess('免费模型池配置已保存');
      } else {
        showError(message || '保存免费模型池失败');
      }
    } catch (e) {
      showError(e.message || '保存免费模型池失败');
    } finally {
      setSaving(false);
    }
  };

  const runAction = async (action, fn, successMessage) => {
    setActingAction(action);
    try {
      const res = await fn();
      if (res.data?.success !== false) {
        showSuccess(successMessage);
        await loadAll(true);
      } else {
        showError(res.data?.message || `${successMessage}失败`);
      }
    } catch (e) {
      showError(e.message || `${successMessage}失败`);
    } finally {
      setActingAction('');
    }
  };

  const runCleanupDryRun = async () => {
    setActingAction('dryrun');
    try {
      const res = await cleanupDryRun();
      if (res.data?.success !== false) {
        const result = res.data.data || res.data.result || {};
        const staleChannels = Array.isArray(result.stale_channels)
          ? result.stale_channels.length
          : 0;
        const staleDeployments = Array.isArray(result.stale_deployments)
          ? result.stale_deployments.length
          : 0;
        showSuccess(`清理预检完成：${staleChannels} 个渠道，${staleDeployments} 个部署`);
      } else {
        showError(res.data?.message || '清理预检失败');
      }
    } catch (e) {
      showError(e.message || '清理预检失败');
    } finally {
      setActingAction('');
    }
  };

  const freeModel = config?.virtual_models?.['cct/free'];
  const usageByProviderKey = useMemo(() => indexUsageRows(usageRows), [usageRows]);
  const freeDeployments = useMemo(() => {
    const deployments = config?.deployments || {};
    return Object.keys(deployments)
      .filter((id) => isAutoFreeDeployment(id, deployments[id]))
      .sort()
      .map((id) => {
        const runtime = runtimeRows.find((row) => row.deployment_id === id) || {};
        return {
          id,
          ...deployments[id],
          runtime: {
            ...runtime,
            health_raw: runtime.health,
            health: formatRuntimeHealth(runtime.health),
          },
        };
      });
  }, [config, runtimeRows]);

  const enabledFreeCount = freeDeployments.filter((dep) => dep.enabled !== false).length;
  const workflowSummary = useMemo(() => buildFreePoolWorkflowSummary({
    config,
    freeDeployments,
    usageRows,
    usageAvailable,
  }), [config, freeDeployments, usageRows, usageAvailable]);

  if (loading) {
    return (
      <div style={{ textAlign: 'center', padding: 60 }}>
        <Loader active inline='centered' />
        <p style={{ marginTop: 12, color: '#868b94' }}>加载免费模型池中...</p>
      </div>
    );
  }

  if (!config) {
    return <Message warning>未加载到免费模型池配置。</Message>;
  }

  return (
    <div className='fallback-config-panel'>
      <div className='fallback-config-toolbar'>
        <Header as='h2' className='fallback-config-title'>
          免费模型池
          <Header.Subheader>
            管理免费模型、免费供应商、限额覆盖和自动生成的免费部署。
          </Header.Subheader>
        </Header>
        <div className='fallback-config-actions'>
          <Button basic icon labelPosition='left' onClick={() => loadAll()} loading={loading}>
            <Icon name='refresh' /> 刷新状态
          </Button>
          <Button
            basic
            icon
            labelPosition='left'
            onClick={() => runAction('reload', reloadConfig, '配置已重新加载')}
            loading={actingAction === 'reload'}
            disabled={!!actingAction}
          >
            <Icon name='sync' /> 重新加载配置
          </Button>
          <Button
            basic
            icon
            labelPosition='left'
            onClick={() => runAction('sync', syncFreePool, '免费池同步完成')}
            loading={actingAction === 'sync'}
            disabled={!!actingAction}
          >
            <Icon name='lightning' /> 同步免费池
          </Button>
          <Button
            basic
            icon
            labelPosition='left'
            onClick={runCleanupDryRun}
            loading={actingAction === 'dryrun'}
            disabled={!!actingAction}
          >
            <Icon name='search' /> 清理预检
          </Button>
          <Button
            primary
            icon
            labelPosition='left'
            onClick={saveFreePoolConfig}
            loading={saving}
            disabled={saving}
          >
            <Icon name='save' /> 保存配置
          </Button>
        </div>
      </div>

      <FreePoolWorkflowDashboard summary={workflowSummary} />

      <section className='fallback-virtual-panel'>
        <div className='fallback-virtual-header'>
          <div>
            <h3>免费模型总览</h3>
            <span>cct/free 使用免费池和免费优先策略。</span>
          </div>
        </div>
        <Table compact celled striped>
          <Table.Header>
            <Table.Row>
              <Table.HeaderCell>免费模型</Table.HeaderCell>
              <Table.HeaderCell>路由池</Table.HeaderCell>
              <Table.HeaderCell>路由策略</Table.HeaderCell>
              <Table.HeaderCell>状态</Table.HeaderCell>
              <Table.HeaderCell>可用免费部署</Table.HeaderCell>
            </Table.Row>
          </Table.Header>
          <Table.Body>
            <Table.Row>
              <Table.Cell>
                <strong>免费模型</strong>
                <div><Label basic color='green'>cct/free</Label></div>
              </Table.Cell>
              <Table.Cell>
                {(freeModel?.pools || ['free'])
                  .map((pool) => POOL_LABELS[pool] || pool)
                  .join(' / ')}
              </Table.Cell>
              <Table.Cell>{STRATEGY_LABELS[freeModel?.strategy] || freeModel?.strategy || '免费优先'}</Table.Cell>
              <Table.Cell>
                {freeModel?.enabled === false ? (
                  <Label basic color='grey'>已停用</Label>
                ) : (
                  <Label basic color='green'>已启用</Label>
                )}
              </Table.Cell>
              <Table.Cell>{enabledFreeCount} / {freeDeployments.length}</Table.Cell>
            </Table.Row>
          </Table.Body>
        </Table>
      </section>

      <section className='fallback-virtual-panel'>
        <div className='fallback-virtual-header'>
          <div>
            <h3>免费供应商</h3>
            <span>OpenRouter、Groq 和限额覆盖。不会显示完整 API key。</span>
          </div>
        </div>
        <FreeProvidersEditor
          freeProviders={config.free_providers || {}}
          freeProviderCatalog={config.free_provider_catalog || []}
          usageByProviderKey={usageByProviderKey}
          onChange={updateFreeProviders}
        />
      </section>

      <section className='fallback-virtual-panel'>
        <div className='fallback-virtual-header'>
          <div>
            <h3>免费供应商用量</h3>
            <span>按供应商、密钥哈希、模型和周期查看只读 token 与请求统计。</span>
          </div>
        </div>
        <Table compact celled striped>
          <Table.Header>
            <Table.Row>
              <Table.HeaderCell>供应商</Table.HeaderCell>
              <Table.HeaderCell>密钥哈希</Table.HeaderCell>
              <Table.HeaderCell>模型</Table.HeaderCell>
              <Table.HeaderCell>周期</Table.HeaderCell>
              <Table.HeaderCell>总 token</Table.HeaderCell>
              <Table.HeaderCell>请求数</Table.HeaderCell>
              <Table.HeaderCell>成功数</Table.HeaderCell>
              <Table.HeaderCell>更新时间</Table.HeaderCell>
            </Table.Row>
          </Table.Header>
          <Table.Body>
            {!usageAvailable ? (
              <Table.Row>
                <Table.Cell colSpan='8'>
                  <Message
                    warning
                    icon='warning sign'
                    header='用量数据不可用'
                    content={usageError || '用量数据不可用。'}
                  />
                </Table.Cell>
              </Table.Row>
            ) : usageRows.length === 0 ? (
              <Table.Row>
                <Table.Cell colSpan='8' textAlign='center'>当前周期暂无用量记录</Table.Cell>
              </Table.Row>
            ) : usageRows.map((row, index) => (
              <Table.Row key={`${row.provider}-${row.key_hash}-${row.model_name}-${row.period}-${index}`}>
                <Table.Cell>{PROVIDER_LABELS[row.provider] || row.provider}</Table.Cell>
                <Table.Cell><Label basic>{row.key_hash}</Label></Table.Cell>
                <Table.Cell>{row.model_name || '-'}</Table.Cell>
                <Table.Cell>{row.period || '-'}</Table.Cell>
                <Table.Cell>{formatNumber(row.total_tokens)}</Table.Cell>
                <Table.Cell>{formatNumber(row.request_count)}</Table.Cell>
                <Table.Cell>{formatNumber(row.success_count)}</Table.Cell>
                <Table.Cell>{row.updated_at ? new Date(row.updated_at).toLocaleString() : '-'}</Table.Cell>
              </Table.Row>
            ))}
          </Table.Body>
        </Table>
      </section>

      <section className='fallback-virtual-panel'>
        <div className='fallback-virtual-header'>
          <div>
            <h3>免费模型部署</h3>
            <span>自动生成的免费部署只读展示，请在免费供应商区域管理。</span>
          </div>
        </div>
        <Table compact celled striped>
          <Table.Header>
            <Table.Row>
              <Table.HeaderCell>部署 ID</Table.HeaderCell>
              <Table.HeaderCell>供应商</Table.HeaderCell>
              <Table.HeaderCell>真实模型</Table.HeaderCell>
              <Table.HeaderCell>额度模式</Table.HeaderCell>
              <Table.HeaderCell>RPM</Table.HeaderCell>
              <Table.HeaderCell>RPD</Table.HeaderCell>
              <Table.HeaderCell>TPM</Table.HeaderCell>
              <Table.HeaderCell>TPD</Table.HeaderCell>
              <Table.HeaderCell>状态</Table.HeaderCell>
            </Table.Row>
          </Table.Header>
          <Table.Body>
            {freeDeployments.length === 0 ? (
              <Table.Row>
                <Table.Cell colSpan='9' textAlign='center'>暂无免费模型部署</Table.Cell>
              </Table.Row>
            ) : (
              freeDeployments.map((dep) => {
                const provider = providerFromDeploymentId(dep.id);
                return (
                  <Table.Row key={dep.id}>
                    <Table.Cell>
                      <strong>{dep.id}</strong>
                      <div style={{ marginTop: 4 }}>
                        <Label basic color='blue' size='mini'>
                          锁定：由免费供应商自动生成
                        </Label>
                      </div>
                    </Table.Cell>
                    <Table.Cell>{PROVIDER_LABELS[provider] || provider}</Table.Cell>
                    <Table.Cell>{dep.real_model || '-'}</Table.Cell>
                    <Table.Cell>{formatQuotaMode(dep.quota_mode)}</Table.Cell>
                    <Table.Cell>{formatLimit(dep.rpm_limit)}</Table.Cell>
                    <Table.Cell>{formatLimit(dep.rpd_limit)}</Table.Cell>
                    <Table.Cell>{formatLimit(dep.tpm_limit)}</Table.Cell>
                    <Table.Cell>{formatLimit(dep.tpd_limit)}</Table.Cell>
                    <Table.Cell>
                      {dep.enabled === false ? (
                        <Label basic color='grey'>已停用</Label>
                      ) : (
                        <>
                          <Label basic color={getRuntimeHealthColor(dep.runtime?.health_raw)}>
                            {dep.runtime?.health || '已启用'}
                          </Label>
                          {renderRuntimeDiagnostics(dep.runtime)}
                        </>
                      )}
                    </Table.Cell>
                  </Table.Row>
                );
              })
            )}
          </Table.Body>
        </Table>
      </section>
    </div>
  );
};

export default FreeModelPool;
